
const projects=[{"id":"01","title":"深圳市华侨城片区发展问题诊断与策划研究","keyword":"问题定义","oneLine":"从资源清单中找出真正的空间瓶颈。","overview":"本项目基于华侨城片区资源、人群活动与空间使用分析，识别园区封闭、交通断连及公共空间不连续等关键问题，提出公共廊道路径、重点节点与分期行动项目，厘清从发展问题诊断到空间策略及项目策划的研究链条，策划若干近期可操作实施的节点性项目。","judgement":"下一步重点是打开边界、建立公共连接，而非继续叠加孤立的功能项目。","metadata":"深圳市南山区；研究范围 18 平方公里；2017—2019 年；委托方为南山区规划局；本人角色为专项负责人。","evidence":"人群需求分析、空间断点诊断、六条廊道、分期行动包。","images":[{"projectId":"01","order":1,"source":"pictures/01 华侨城片区综合研究_6页/幻灯片1.JPG","src":"assets/01-01.jpg","width":1280,"height":720,"data":"assets/image-c0a7c551b6e4ae5acd87.webp"},{"projectId":"01","order":2,"source":"pictures/01 华侨城片区综合研究_6页/幻灯片2.JPG","src":"assets/01-02.jpg","width":1280,"height":720,"data":"assets/image-8aca91272e7a670df9f5.webp"},{"projectId":"01","order":3,"source":"pictures/01 华侨城片区综合研究_6页/幻灯片3.JPG","src":"assets/01-03.jpg","width":1280,"height":720,"data":"assets/image-7427a390dbe167c42635.webp"},{"projectId":"01","order":4,"source":"pictures/01 华侨城片区综合研究_6页/幻灯片4.JPG","src":"assets/01-04.jpg","width":1280,"height":720,"data":"assets/image-889daa33a6b94efddabe.webp"},{"projectId":"01","order":5,"source":"pictures/01 华侨城片区综合研究_6页/幻灯片5.JPG","src":"assets/01-05.jpg","width":1280,"height":720,"data":"assets/image-4b4fd599b6a55297c4e8.webp"},{"projectId":"01","order":6,"source":"pictures/01 华侨城片区综合研究_6页/幻灯片6.JPG","src":"assets/01-06.jpg","width":1280,"height":720,"data":"assets/image-4d519a70e2a4dfa4ab8d.webp"}]},{"id":"02","title":"中新广州知识城产业园区空间布局与规划系列研究","keyword":"产业转译","oneLine":"把企业的生产条件写进园区的空间条件。","overview":"为支撑中新广州知识城新兴产业落地，受知识城国规处委托，本项目统筹政策与产业研究、企业需求及空间约束分析，将产业发展需求转化为用地规模、交通市政配套及规划控制条件，提出园区空间布局方案与实施路径，推动合成生物、低空经济及集成电路3个产业园区规划成果通过市区级审查。","judgement":"园区规划不能套用同一组强度和配套指标，先要明确企业如何生产、测试与成长。","metadata":"广州市黄埔区；2025—2026 年；委托方为中新知识城建设办；本人角色为技术负责人。三个子案例分别标注研究范围：合成生物 80.2 公顷、集成电路 480 公顷、低空经济 110 公顷。","evidence":"三类产业的差异化需求总表；合成生物研发—中试—转化载体链；集成电路连片用地、货运与环境门槛；低空经济跑道、厂房和净空控制。","images":[{"projectId":"02","order":1,"source":"pictures/02 广州产业园区规划与发展咨询/幻灯片1.JPG","src":"assets/02-01.jpg","width":4400,"height":2475,"data":"assets/image-7550630ada416e0f3d1e.webp"},{"projectId":"02","order":2,"source":"pictures/02 广州产业园区规划与发展咨询/幻灯片2.JPG","src":"assets/02-02.jpg","width":4400,"height":2475,"data":"assets/image-4750f3d59dbea685d6d7.webp"},{"projectId":"02","order":3,"source":"pictures/02 广州产业园区规划与发展咨询/幻灯片3.JPG","src":"assets/02-03.jpg","width":4400,"height":2475,"data":"assets/image-df1d3e760d9a68c67f1e.webp"},{"projectId":"02","order":4,"source":"pictures/02 广州产业园区规划与发展咨询/幻灯片4.JPG","src":"assets/02-04.jpg","width":4400,"height":2475,"data":"assets/image-2f31205392ef8d7b115f.webp"},{"projectId":"02","order":5,"source":"pictures/02 广州产业园区规划与发展咨询/幻灯片5.JPG","src":"assets/02-05.jpg","width":4400,"height":2475,"data":"assets/image-eafbfe5dde3675e2cc5d.webp"},{"projectId":"02","order":6,"source":"pictures/02 广州产业园区规划与发展咨询/幻灯片6.JPG","src":"assets/02-06.jpg","width":4400,"height":2475,"data":"assets/image-6bbca587626cd31f67c2.webp"},{"projectId":"02","order":7,"source":"pictures/02 广州产业园区规划与发展咨询/幻灯片7.JPG","src":"assets/02-07.jpg","width":4400,"height":2475,"data":"assets/image-01de2fbd1a8229e2be58.webp"}]},{"id":"03","title":"深圳市龙华区旧工业区综合整治更新政策研究与制度设计","keyword":"制度设计","oneLine":"让高频、局部的园区改善诉求有规则可依。","overview":"针对龙华旧工业园区高频改善需求，本项目立足龙华区更新局职能，系统梳理市区两级更新政策脉络，开展园区需求诊断与政策堵点分析，提出更新政策编制方案及发布程序，将园区发展诉求转化为可申请、可审批、可监管的政策文件，为区级更新政策出台提供直接支撑。","judgement":"旧工业园提质并不总需要拆除重建；对合理的渐进式改造，应建立可申请、可审批、可监管的政策通道。","metadata":"深圳市龙华区；2022—2024 年；委托方为龙华区城市更新局；本人角色为驻场咨询师。","evidence":"企业需求分类、诉求与现行规则的断点、政策工具与审批路径、正式发布的成果节点。","images":[{"projectId":"03","order":1,"source":"pictures/03 深圳龙华区旧工业区更新实施研究_6页_v2/幻灯片1.JPG","src":"assets/03-01.jpg","width":2933,"height":1650,"data":"assets/image-6aa4986f6730cd12b4d9.webp"},{"projectId":"03","order":2,"source":"pictures/03 深圳龙华区旧工业区更新实施研究_6页_v2/幻灯片2.JPG","src":"assets/03-02.jpg","width":2933,"height":1650,"data":"assets/image-ad3206b59f3b48044c76.webp"},{"projectId":"03","order":3,"source":"pictures/03 深圳龙华区旧工业区更新实施研究_6页_v2/幻灯片3.JPG","src":"assets/03-03.jpg","width":2933,"height":1650,"data":"assets/image-ae94b75f81124e7efbb3.webp"},{"projectId":"03","order":4,"source":"pictures/03 深圳龙华区旧工业区更新实施研究_6页_v2/幻灯片4.JPG","src":"assets/03-04.jpg","width":2933,"height":1650,"data":"assets/image-b83a3bc3ccb14cb11975.webp"},{"projectId":"03","order":5,"source":"pictures/03 深圳龙华区旧工业区更新实施研究_6页_v2/幻灯片5.JPG","src":"assets/03-05.jpg","width":2933,"height":1650,"data":"assets/image-f523788ce25263d33036.webp"},{"projectId":"03","order":6,"source":"pictures/03 深圳龙华区旧工业区更新实施研究_6页_v2/幻灯片6.JPG","src":"assets/03-06.jpg","width":2933,"height":1650,"data":"assets/image-650d8d294daf5236080c.webp"}]},{"id":"04","title":"深圳龙岗河龙园片区城市设计方案比选与实施研究","keyword":"决策支持","oneLine":"把设计愿景放进工程与土地条件中重新检验。","overview":"受龙岗区更新局委托，在龙岗河龙园片区国际咨询竞赛取得第一名基础上，进一步检验滨水场所、交通、地下联系与既有村落更新的实施条件。比较多方案的工程可行性及其对片区产生的影响，提出推荐方案并明确推荐理由、防洪条件与土地更新约束。","judgement":"推荐方案的说服力来自公开说明取舍：保留一定的滨水与地面步行连续性，同时控制工程量和更新地块影响。","metadata":"深圳市龙岗区；研究范围 82 公顷；2019 年；委托方为龙岗区更新局；合作团队为 KCAP；本人角色为专项负责人；国际咨询竞赛第一名。","evidence":"龙园路三方案比较、推荐理由、接受的代价、防洪与土地更新约束。","images":[{"projectId":"04","order":1,"source":"pictures/04 深圳龙岗河龙园片区国际咨询_6页/幻灯片1.JPG","src":"assets/04-01.jpg","width":2933,"height":1650,"data":"assets/image-a4201a3a86b647b8bc89.webp"},{"projectId":"04","order":2,"source":"pictures/04 深圳龙岗河龙园片区国际咨询_6页/幻灯片2.JPG","src":"assets/04-02.jpg","width":2933,"height":1650,"data":"assets/image-dcb22f1f97d22ffb6abc.webp"},{"projectId":"04","order":3,"source":"pictures/04 深圳龙岗河龙园片区国际咨询_6页/幻灯片3.JPG","src":"assets/04-03.jpg","width":2933,"height":1650,"data":"assets/image-6300118e567230194e1e.webp"},{"projectId":"04","order":4,"source":"pictures/04 深圳龙岗河龙园片区国际咨询_6页/幻灯片4.JPG","src":"assets/04-04.jpg","width":2933,"height":1650,"data":"assets/image-f49894c74be1b87dbbe9.webp"},{"projectId":"04","order":5,"source":"pictures/04 深圳龙岗河龙园片区国际咨询_6页/幻灯片5.JPG","src":"assets/04-05.jpg","width":2933,"height":1650,"data":"assets/image-5f86226e7cb7e8fe88aa.webp"}]},{"id":"05","title":"深圳市后海中心区城市设计实施评估与管控图则深化研究","keyword":"实施管控","oneLine":"把十余年建设经验转成下一阶段可使用的控制工具。","overview":"本项目通过评估后海中心区2017年建设状态，总结实施中遇到的问题，提出统筹公共空间、首层界面、二层连廊和地下空间的控制策略，并将策略转化为可落地的管控图则和实施管理“一张图”，为后续报建审查与分期建设提供直接依据。","judgement":"下一阶段工作的重点不是重新绘制总图，而是把跨地块网络和工程接口写清楚。","metadata":"深圳市南山区；226 公顷（2.26 平方公里）；2017—2021 年；委托方为南山区后海重点办；本人角色为专项负责人。","evidence":"实施状态分析、复合慢行网络、增补图则的控制要素、“一张图”实施管理。","images":[{"projectId":"05","order":1,"source":"pictures/05 后海中心区_实施评估与管控_方案B_7页可编辑稿_v4/幻灯片1.JPG","src":"assets/05-01.jpg","width":2933,"height":1650,"data":"assets/image-ee76c0d70b214e149ca9.webp"},{"projectId":"05","order":2,"source":"pictures/05 后海中心区_实施评估与管控_方案B_7页可编辑稿_v4/幻灯片2.JPG","src":"assets/05-02.jpg","width":2933,"height":1650,"data":"assets/image-bb74ab2d91fe29f7fa29.webp"},{"projectId":"05","order":3,"source":"pictures/05 后海中心区_实施评估与管控_方案B_7页可编辑稿_v4/幻灯片3.JPG","src":"assets/05-03.jpg","width":2933,"height":1650,"data":"assets/image-60399b69d3b3b8bae84c.webp"},{"projectId":"05","order":4,"source":"pictures/05 后海中心区_实施评估与管控_方案B_7页可编辑稿_v4/幻灯片4.JPG","src":"assets/05-04.jpg","width":2933,"height":1650,"data":"assets/image-d7274c8a661c152a6cef.webp"},{"projectId":"05","order":5,"source":"pictures/05 后海中心区_实施评估与管控_方案B_7页可编辑稿_v4/幻灯片5.JPG","src":"assets/05-05.jpg","width":2933,"height":1650,"data":"assets/image-b8e01cc2ee90c8191fdd.webp"},{"projectId":"05","order":6,"source":"pictures/05 后海中心区_实施评估与管控_方案B_7页可编辑稿_v4/幻灯片6.JPG","src":"assets/05-06.jpg","width":2933,"height":1650,"data":"assets/image-23ce948c27a03108884b.webp"},{"projectId":"05","order":7,"source":"pictures/05 后海中心区_实施评估与管控_方案B_7页可编辑稿_v4/幻灯片7.JPG","src":"assets/05-07.jpg","width":2933,"height":1650,"data":"assets/image-68f1e7b1fd758f7a4897.webp"}]},{"id":"06","title":"深圳市龙华区超级商圈城市设计与实施统筹研究","keyword":"多方统筹","oneLine":"让分期建设的地块共同形成一个商圈。","overview":"本项目受龙华区更新局委托，围绕7个更新单元，统筹政府、开发主体与设计团队多方诉求，组织方案整合、技术审查、意见反馈及实施跟踪，明确跨地块公共空间与立体慢行系统的衔接标准，形成共同管控要求，为片区统筹开发提供可执行的协同机制。","judgement":"单个地块可以独立实施，但连接位置、竖向转换和公共界面必须提前形成共同规则。","metadata":"深圳市龙华区；城市设计研究范围 3.25 平方公里；2022—2024 年；委托方为龙华区更新局；协作团队包括 HPP；本人角色为驻场项目负责人。","evidence":"三层公共空间系统、地块接口控制、项目库与分期任务、协调意见及报建反馈。","images":[{"projectId":"06","order":1,"source":"pictures/06 龙华超级商圈_7页/幻灯片1.JPG","src":"assets/06-01.jpg","width":2933,"height":1650,"data":"assets/image-904fb1dafa43e3005353.webp"},{"projectId":"06","order":2,"source":"pictures/06 龙华超级商圈_7页/幻灯片2.JPG","src":"assets/06-02.jpg","width":2933,"height":1650,"data":"assets/image-a8fb2396a37b2c387107.webp"},{"projectId":"06","order":3,"source":"pictures/06 龙华超级商圈_7页/幻灯片3.JPG","src":"assets/06-03.jpg","width":2933,"height":1650,"data":"assets/image-38471045ea966d3a4d99.webp"},{"projectId":"06","order":4,"source":"pictures/06 龙华超级商圈_7页/幻灯片4.JPG","src":"assets/06-04.jpg","width":2933,"height":1650,"data":"assets/image-d4e84719242880667452.webp"},{"projectId":"06","order":5,"source":"pictures/06 龙华超级商圈_7页/幻灯片5.JPG","src":"assets/06-05.jpg","width":2933,"height":1650,"data":"assets/image-91be64bb8adee9faf422.webp"},{"projectId":"06","order":6,"source":"pictures/06 龙华超级商圈_7页/幻灯片6.JPG","src":"assets/06-06.jpg","width":2933,"height":1650,"data":"assets/image-36df176bf87aceb719d5.webp"}]},{"id":"07","title":"九江赛城湖新区起步区发展定位与空间规划研究","keyword":"项目领导","oneLine":"统一战略主线，组织跨团队的方案与交付。","overview":"受八里湖管委会委托，针对起步区港城产业、山湖资源与城市生活交织的复杂条件，项目以「赛湖造市」为主线，以绿谷与山水廊道组织空间骨架，提出功能组团与重点场景的战略定位与实施路径。成果包括三条研究线索与战略定位、绿谷及山水廊道骨架，并形成 95 页双语报告及多媒介成果交付。","judgement":"赛城湖的价值在于将产业动力、区域山湖资源和本地生活需求放在同一个城市框架中，而不是单独开发一个景区或园区。","metadata":"江西省九江市；研究范围 180 公顷；2021 年；委托方为八里湖管委会；合作团队为荷兰 MLA+；本人角色为项目负责人；国际竞赛第三名。","evidence":"三条研究线索与战略定位、绿谷及山水廊道骨架、5 人团队分工、阶段关口、95 页双语报告及多媒介交付。","images":[{"projectId":"07","order":1,"source":"pictures/07_九江赛城湖新区起步区_A主版可编辑/幻灯片1.JPG","src":"assets/07-01.jpg","width":1280,"height":720,"data":"assets/image-cbf15f6977eedb35b8a1.webp"},{"projectId":"07","order":2,"source":"pictures/07_九江赛城湖新区起步区_A主版可编辑/幻灯片2.JPG","src":"assets/07-02.jpg","width":1280,"height":720,"data":"assets/image-480461758fc744768764.webp"},{"projectId":"07","order":3,"source":"pictures/07_九江赛城湖新区起步区_A主版可编辑/幻灯片3.JPG","src":"assets/07-03.jpg","width":1280,"height":720,"data":"assets/image-92850497b2221d5fb4be.webp"},{"projectId":"07","order":4,"source":"pictures/07_九江赛城湖新区起步区_A主版可编辑/幻灯片4.JPG","src":"assets/07-04.jpg","width":1280,"height":720,"data":"assets/image-8e5f21a160a79514e44c.webp"},{"projectId":"07","order":5,"source":"pictures/07_九江赛城湖新区起步区_A主版可编辑/幻灯片5.JPG","src":"assets/07-05.jpg","width":1280,"height":720,"data":"assets/image-4fde3eef4b1d909e9c7f.webp"},{"projectId":"07","order":6,"source":"pictures/07_九江赛城湖新区起步区_A主版可编辑/幻灯片6.JPG","src":"assets/07-06.jpg","width":1280,"height":720,"data":"assets/image-70b7588c2020ead0b475.webp"}]}];
