function createMobilePhotoGesture(viewport,image,onTap,onScaleChange){
  const pointers=new Map();
  let state={scale:1,x:0,y:0,width:0,height:0};
  let gesture=null;
  let blockedClick=false;
  let blockedUntil=0;
  let fallbackWidth=1,fallbackHeight=1;
  function paint(){
    const maxX=Math.max(0,(state.width*state.scale-viewport.clientWidth)/2);
    const maxY=Math.max(0,(state.height*state.scale-viewport.clientHeight)/2);
    state.x=Math.min(maxX,Math.max(-maxX,state.x));
    state.y=Math.min(maxY,Math.max(-maxY,state.y));
    image.style.transform='translate(-50%,-50%) translate('+state.x+'px,'+state.y+'px) scale('+state.scale+')';
    if(onScaleChange)onScaleChange(state.scale);
  }
  function fit(){
    const width=viewport.clientWidth,height=viewport.clientHeight;
    if(width<=0||height<=0)return;
    const iw=image.complete&&image.naturalWidth?image.naturalWidth:fallbackWidth;
    const ih=image.complete&&image.naturalHeight?image.naturalHeight:fallbackHeight;
    const factor=Math.min(width/iw,height/ih);
    state.width=iw*factor;state.height=ih*factor;
    image.style.width=state.width+'px';image.style.height=state.height+'px';
    paint();
  }
  function reset(width=1,height=1){
    pointers.clear();gesture=null;blockedClick=false;blockedUntil=0;
    fallbackWidth=width;fallbackHeight=height;
    state={scale:1,x:0,y:0,width:0,height:0};
    fit();
  }
  function begin(){
    const points=[...pointers.values()],rect=viewport.getBoundingClientRect();
    if(points.length>=2){
      const a=points[0],b=points[1];
      blockedClick=true;
      gesture={count:2,distance:Math.max(1,Math.hypot(a.x-b.x,a.y-b.y)),
        cx:(a.x+b.x)/2-rect.left-rect.width/2,
        cy:(a.y+b.y)/2-rect.top-rect.height/2,...state};
    }else if(points.length===1){
      gesture={count:1,startX:points[0].x,startY:points[0].y,...state};
    }else gesture=null;
  }
  function down(id,x,y){
    if(pointers.size===0){blockedClick=false;blockedUntil=0;}
    pointers.set(id,{x,y});begin();
  }
  function move(id,x,y){
    if(!pointers.has(id))return;
    pointers.set(id,{x,y});
    const points=[...pointers.values()];
    if(!gesture)return;
    if(gesture.count===2&&points.length>=2){
      const a=points[0],b=points[1],rect=viewport.getBoundingClientRect();
      const nextScale=Math.max(1,Math.min(6,gesture.scale*Math.hypot(a.x-b.x,a.y-b.y)/gesture.distance));
      const ratio=nextScale/gesture.scale;
      state.scale=nextScale;
      state.x=(a.x+b.x)/2-rect.left-rect.width/2-(gesture.cx-gesture.x)*ratio;
      state.y=(a.y+b.y)/2-rect.top-rect.height/2-(gesture.cy-gesture.y)*ratio;
    }else if(gesture.count===1){
      const dx=points[0].x-gesture.startX,dy=points[0].y-gesture.startY;
      if(Math.hypot(dx,dy)>12)blockedClick=true;
      state.x=gesture.x+dx;state.y=gesture.y+dy;
    }
    paint();
  }
  function up(id,cancelled=false){
    if(!pointers.has(id))return;
    if(cancelled)blockedClick=true;
    pointers.delete(id);
    if(blockedClick)blockedUntil=Date.now()+500;
    begin();
  }
  if('PointerEvent' in window){
    viewport.addEventListener('pointerdown',event=>{
      if(event.pointerType==='mouse'&&event.button!==0)return;
      down(event.pointerId,event.clientX,event.clientY);
      viewport.setPointerCapture(event.pointerId);
    });
    viewport.addEventListener('pointermove',event=>move(event.pointerId,event.clientX,event.clientY));
    viewport.addEventListener('pointerup',event=>up(event.pointerId));
    viewport.addEventListener('pointercancel',event=>up(event.pointerId,true));
    viewport.addEventListener('lostpointercapture',event=>up(event.pointerId,true));
  }else{
    viewport.addEventListener('touchstart',event=>{
      for(const touch of event.changedTouches)down(touch.identifier,touch.clientX,touch.clientY);
    },{passive:true});
    viewport.addEventListener('touchmove',event=>{
      event.preventDefault();
      for(const touch of event.changedTouches)move(touch.identifier,touch.clientX,touch.clientY);
    },{passive:false});
    viewport.addEventListener('touchend',event=>{
      for(const touch of event.changedTouches)up(touch.identifier);
    },{passive:true});
    viewport.addEventListener('touchcancel',event=>{
      for(const touch of event.changedTouches)up(touch.identifier,true);
    },{passive:true});
  }
  viewport.addEventListener('click',event=>{
    if(blockedClick&&Date.now()<blockedUntil)return;
    if(pointers.size>0)return;
    event.stopPropagation();
    onTap();
  });
  image.addEventListener('load',fit);
  new ResizeObserver(fit).observe(viewport);
  function toggleZoom(){
    blockedClick=false;blockedUntil=0;
    state.scale=state.scale>1?1:2;
    state.x=0;state.y=0;paint();
  }
  return {reset,fit,toggleZoom};
}

