const mobileNativeRoot = document.getElementById('mobileNativeContent');
const mobileNativeSections = {
  top:document.getElementById("mobileNativePersonal"),
  competencies:document.getElementById("mobileNativeCompetencies"),
  experience:document.getElementById('mobileNativeExperience'),
  certificates:document.getElementById('mobileNativeCertificates')
};
const mobilePersonalHost=document.getElementById("mobilePersonalRoot");
const mobilePersonalShadow=mobilePersonalHost.attachShadow({mode:"open"});
mobilePersonalShadow.append(document.getElementById("mobilePersonalTemplate").content.cloneNode(true));
const mobileCertificateGrid = document.getElementById('mobileNativeCertificateGrid');
const mobileCertificateSlides = nativeMobileCertificates.flatMap((certificate,certificateIndex) =>
  certificate.images.map(src => ({certificate,certificateIndex,src}))
);
const mobileCertificateDialog = document.getElementById('mobileCertificateDialog');
const mobileCertificateViewport = document.getElementById('mobileCertificateViewport');
const mobileCertificateImage = document.getElementById('mobileCertificateImage');
const mobileCertificateZoomButton = document.getElementById('mobileCertificateZoomButton');
let nativeCertificateIndex = 0;
let nativeCertificateTrigger = null;
const certificatePhotoGesture=createMobilePhotoGesture(mobileCertificateViewport,mobileCertificateImage,()=>{
  if(mobileCertificateDialog.open)mobileCertificateDialog.close();
},scale=>{
  mobileCertificateZoomButton.textContent=scale>1?"适应屏幕":"放大查看";
  mobileCertificateZoomButton.setAttribute("aria-pressed",String(scale>1));
});
nativeMobileCertificates.forEach((certificate,index) => {
  const button = document.createElement('button');
  button.type = 'button';
  button.className = 'mobile-native-certificate';
  button.dataset.certificate = String(index);
  button.setAttribute('aria-label','查看'+certificate.title+'大图');
  const preview = document.createElement('img');
  preview.src = certificate.images[0];
  preview.alt = certificate.title;
  preview.loading = 'lazy';
  preview.decoding = 'async';
  const title = document.createElement('strong');
  title.textContent = certificate.title;
  const description = document.createElement('small');
  description.textContent = certificate.subtitle;
  const action = document.createElement('span');
  action.textContent = '查看大图 ↗';
  button.append(preview,title,description,action);
  mobileCertificateGrid.append(button);
});
function syncNativeMobileView(view){
  const native=mobileHomepage.matches&&Object.hasOwn(mobileNativeSections,view);
  const overlay=document.getElementById("sectionOverlay");
  mobileNativeRoot.hidden=!native;
  if(native)overlay.dataset.nativeMobile=view;
  else delete overlay.dataset.nativeMobile;
  for(const panel of Object.values(mobileNativeSections))panel.hidden=false;
  if(native){
    const panel=mobileNativeSections[view];
    const top=panel.getBoundingClientRect().top-mobileNativeRoot.getBoundingClientRect().top+mobileNativeRoot.scrollTop-24;
    mobileNativeRoot.scrollTo({top:Math.max(0,top),behavior:"instant"});
  }
  return native;
}
function resetNativeCertificateZoom(){certificatePhotoGesture.reset();}
function renderNativeCertificate(){
  const slide = mobileCertificateSlides[nativeCertificateIndex];
  mobileCertificateImage.src = slide.src;
  mobileCertificateImage.alt = slide.certificate.title;
  document.getElementById('mobileCertificateTitle').textContent = slide.certificate.title;
  document.getElementById('mobileCertificateCounter').textContent = (nativeCertificateIndex+1)+' / '+mobileCertificateSlides.length;
  const metadata = document.getElementById('mobileCertificateMetadata');
  metadata.replaceChildren();
  [slide.certificate.subtitle,slide.certificate.detail,slide.certificate.date].filter(Boolean).forEach(text => {
    const line=document.createElement('p');
    line.textContent=text;
    metadata.append(line);
  });
  document.getElementById('mobileCertificatePrevious').disabled = nativeCertificateIndex===0;
  document.getElementById('mobileCertificateNext').disabled = nativeCertificateIndex===mobileCertificateSlides.length-1;
  resetNativeCertificateZoom();
}
function openNativeCertificate(index,trigger){
  const first = mobileCertificateSlides.findIndex(slide=>slide.certificateIndex===index);
  if(first<0)return;
  nativeCertificateIndex=first;
  nativeCertificateTrigger=trigger;
  renderNativeCertificate();
  mobileCertificateDialog.showModal();certificatePhotoGesture.fit();
  document.getElementById('mobileCertificateClose').focus({preventScroll:true});
}
mobileCertificateGrid.addEventListener('click',event=>{
  const button=event.target.closest('button[data-certificate]');
  if(button&&mobileCertificateGrid.contains(button))openNativeCertificate(Number(button.dataset.certificate),button);
});
document.getElementById('mobileCertificateClose').onclick=()=>mobileCertificateDialog.close();
mobileCertificateDialog.addEventListener('close',()=>{
  resetNativeCertificateZoom();
  nativeCertificateTrigger?.focus({preventScroll:true});
});
function shiftNativeCertificate(delta){
  nativeCertificateIndex=Math.max(0,Math.min(mobileCertificateSlides.length-1,nativeCertificateIndex+delta));
  renderNativeCertificate();
}
document.getElementById('mobileCertificatePrevious').onclick=()=>shiftNativeCertificate(-1);
document.getElementById('mobileCertificateNext').onclick=()=>shiftNativeCertificate(1);
mobileCertificateZoomButton.onclick=()=>certificatePhotoGesture.toggleZoom();
mobileCertificateDialog.addEventListener('keydown',event=>{
  if(event.key==='ArrowLeft'||event.key==='ArrowRight'){
    event.preventDefault();shiftNativeCertificate(event.key==='ArrowRight'?1:-1);
  }
});
mobileHomepage.addEventListener('change',()=>{
  if(mobileCertificateDialog.open)mobileCertificateDialog.close();
  const selected=document.querySelector('.main-nav button.active');
  if(selected)activateView(selected.dataset.view);
});

const projectImageDialog=document.getElementById('mobileProjectImageDialog');
const projectImageViewport=document.getElementById('mobileProjectImageViewport');
const projectImagePhoto=document.getElementById('mobileProjectImagePhoto');
let projectImageReturnScroll=0;
let projectImageReturnTrigger=null;
const projectPhotoGesture=createMobilePhotoGesture(projectImageViewport,projectImagePhoto,()=>{
  if(projectImageDialog.open)projectImageDialog.close();
});
function openMobileProjectImage(index){
  imageIndex=index;
  const image=projects[detailProject].images[index];
  projectImageReturnScroll=document.getElementById('gallery').scrollTop;
  projectImageReturnTrigger=document.getElementById('gallery').querySelectorAll('[data-image]')[index];
  projectImagePhoto.src=image.data;
  projectImagePhoto.alt=projects[detailProject].title+' · 第'+(index+1)+'页';
  document.getElementById('mobileProjectImageCounter').textContent=(index+1)+' / '+projects[detailProject].images.length;
  projectImageDialog.showModal();
  projectPhotoGesture.reset(image.width,image.height);
  document.getElementById('mobileProjectImageClose').focus({preventScroll:true});
}
document.getElementById('mobileProjectImageClose').onclick=()=>projectImageDialog.close();
projectImageDialog.addEventListener('close',()=>{
  projectPhotoGesture.reset();
  projectImageReturnTrigger?.focus({preventScroll:true});
  document.getElementById('gallery').scrollTop=projectImageReturnScroll;
});
mobileHomepage.addEventListener('change',()=>{if(projectImageDialog.open)projectImageDialog.close()});


